                    lines += 1
                    current_line_width = word_width
                    if lines > m:
                        return False
                else:
                    current_line_width += 1 + word_width

        return True

    # Binary search on the answer
    left = max(L)  # At least as wide as the longest word
    right = sum(L) + (n - 1)  # Worst case: all words in one line with spaces

    while left < right:
        mid = (left + right) // 2
        if can_fit(mid):
            right = mid
        else:
            left = mid + 1

