def findMissingAndRepeatedValues(grid):
    n = len(grid)
    total_size = n * n

    # Flatten the grid and count frequencies
    seen = {}
    for row in grid:
        for val in row:
            seen[val] = seen.get(val, 0) + 1

    # Find the repeated number (appears twice)
    a = None
    for val, count in seen.items():
        if count == 2:
            a = val
            break

    # Find the missing number (doesn't appear in the grid)
    b = None
    for i in range(1, total_size + 1):
        if i not in seen:
            b = i
            break

    return [a, b]
