def maximumPrimeDifference(nums):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Find all indices of prime numbers
    prime_indices = []
    for i in range(len(nums)):
        if is_prime(nums[i]):
            prime_indices.append(i)

    # Return the maximum distance between any two prime indices
    return prime_indices[-1] - prime_indices[0]
