def solve():
    import sys
    from itertools import permutations

    # Read input
    lines = sys.stdin.read().splitlines()
    if not lines:
        print("No")
        return

    N, H, W = map(int, lines[0].split())
    tiles = []
    for i in range(1, N + 1):
        a, b = map(int, lines[i].split())
        # Store both orientations of the tile
        tiles.append((a, b))
        tiles.append((b, a))

    # Total cells in the grid
    total_cells = H * W
    grid = [[0] * W for _ in range(H)]  # 0 means empty, 1 means filled

    def can_place(r, c, h, w):
        """Check if a tile of size h x w can be placed at position (r, c)"""
        if r + h > H or c + w > W:
            return False
        for i in range(r, r + h):
            for j in range(c, j + w):
                if grid[i][j] == 1:
                    return False
        return True

    def place_tile(r, c, h, w, value):
        """Place or remove a tile of size h x w at position (r, c)"""
        for i in range(r, r + h):
            for j in range(c, c + w):
                grid[i][j] = value

    def backtrack(idx):
        """Try to fill the grid starting from cell idx"""
        if idx == total_cells:
            return True

        r, c = idx // W, idx % W
        if grid[r][c] == 1:
            return backtrack(idx + 1)

        # Try each tile
        for i in range(len(tiles)):
            h, w = tiles[i]

            # Skip if tile is too big
            if r + h > H or c + w > W:
                continue

            # Check if we can place this tile
            can_place_tile = True
            for dr in range(h):
                for dc in range(w):
                    if grid[r + dr][c + dc] == 1:
                        can_place_tile = False
                        break
                if not can_place_tile:
                    break

            if can_place_tile:
                # Place the tile
                place_tile(r, c, h, w, 1)

                # Recurse
                if backtrack(idx + 1):
                    return True

                # Remove the tile (backtrack)
                place_tile(r, c, h, w, 0)

        return False

    # Use recursive backtracking to try all combinations
    # But first check if total area of tiles >= grid area
    max_area = sum(max(a, b) * min(a, b) for a, b in [tiles[i] for i in range(0, len(tiles), 2)])

    if max_area < total_cells:
        print("No")
        return

    # Try to fill the grid
    if backtrack(0):
        print("Yes")
    else:
        print("No")

