def maximumJumps(nums, target):
    n = len(nums)
    # dp[i] represents the maximum number of jumps to reach index i
    dp = [-1] * n
    dp[0] = 0  # starting point

    for i in range(n):
        if dp[i] == -1:
            continue  # cannot reach this index

        for j in range(i + 1, n):
            diff = nums[j] - nums[i]
            if -target <= diff <= target:
                if dp[i] != -1:
                    if dp[j] == -1:
                        dp[j] = dp[i] + 1
                    else:
                        dp[j] = max(dp[j], dp[i] + 1)

    return dp[n - 1]
```

