def isValid(word):
    # Check minimum length of 3
    if len(word) < 3:
        return False

    # Define vowels
    vowels = set('aeiouAEIOU')

    # Check if word contains only allowed characters (digits and English letters)
    for char in word:
        if not (char.isalnum() and char.isalpha() or char.isdigit()):
            return False

    # Check if word contains at least one vowel and one consonant
    has_vowel = False
    has_consonant = False

    for char in word:
        if char.isalpha():
            if char in vowels:
                has_vowel = True
            else:
                has_consonant = True

    return has_vowel and has_consonant
