def solve():
    import sys
    from itertools import permutations

    # Read input
    lines = []
    for line in sys.stdin:
        lines.append(line.strip())

    # Parse the three polyominoes
    polyominoes = []
    for i in range(3):
        grid = []
        for j in range(4):
            grid.append(list(lines[i*4 + j]))
        polyominoes.append(grid)

    # Function to get all possible placements (rotations and translations) of a polyomino
    def get_all_placements(poly):
        placements = []
        # Try all 4 rotations
        for rot in range(4):
            if rot == 0:
                rotated = [row[:] for row in poly]
            elif rot == 1:
                rotated = [[poly[3-j][i] for j in range(4)] for i in range(4)]
            elif rot == 2:
                rotated = [[poly[3-i][3-j] for j in range(4)] for i in range(4)]
            else: # rot == 3
                rotated = [[poly[j][3-i] for j in range(4)] for i in range(4)]

            # Get the actual shape (minimally translated to top-left)
            min_i, min_j = 4, 4
            max_i, max_j = -1, -1
            for i in range(4):
                for j in range(4):
                    if rotated[i][j] == '#':
                        min_i = min(min_i, i)
                        min_j = min(min_j, j)
                        max_i = max(max_i, i)
                        max_j = max(max_j, j)

            # If the polyomino is empty, skip
            if min_i == 4:
                continue

            # Extract the relative coordinates of the '#' cells
            shape = []
            for i in range(min_i, max_i + 1):
                for j in range(min_j, max_j + 1):
                    if rotated[i][j] == '#':
                        shape.append((i - min_i, j - min_j))

            # Try all possible translations within the 4x4 grid
            height = max_i - min_i + 1
            width = max_j - min_j + 1

            for offset_i in range(4 - height + 1):
                for offset_j in range(4 - width + 1):
                    placement = set()
                    for di, dj in shape:
                        placement.add((offset_i + di, offset_j + dj))
                    placements.append(placement)

        # Remove duplicates
        unique_placements = []
        for p in placements:
            if p not in unique_placements:
                unique_placements.append(p)
        return unique_placements

    # Get all possible placements for each polyomino
    all_placements = []
    for poly in polyominoes:
        placements = get_all_placements(poly)
        all_placements.append(placements)

    # Check all permutations of polyominoes and their placements
    for perm in permutations(range(3)):
        for p1 in all_placements[perm[0]]:
            for p2 in all_placements[perm[1]]:
                # Check if p1 and p2 overlap
                if p1 & p2:
                    continue
                for p3 in all_placements[perm[2]]:
                    # Check if p3 overlaps with p1 or p2
                    if p3 & p1 or p3 & p2:
                        continue
                    # Check if all cells are covered
                    union = p1 | p2 | p3
                    if len(union) == 16:  # 4x4 grid
                        print("Yes")
                        return

    print("No")

