def maximumEnergy(energy, k):
    n = len(energy)
    # Create dp array to store maximum energy starting from each position
    dp = [0] * n

    # Fill dp array from right to left
    for i in range(n - 1, -1, -1):
        # Base case: if we're at a position where next jump goes out of bounds
        if i + k >= n:
            dp[i] = energy[i]
        else:
            # Otherwise, take current energy plus best path from next position
            dp[i] = energy[i] + dp[i + k]

    # Return the maximum energy we can get from any starting position
    return max(dp)
