def sortVowels(s):
    vowels = set('aeiouAEIOU')
    s_vowels = []

    # Extract all vowels from the string
    for char in s:
        if char in vowels:
            s_vowels.append(char)

    # Sort vowels by ASCII value
    s_vowels.sort()

    # Reconstruct the string with sorted vowels
    result = []
    vowel_index = 0

    for char in s:
        if char in vowels:
            result.append(s_vowels[vowel_index])
            vowel_index += 1
        else:
            result.append(char)

    return ''.join(result)
