def countBeautifulIntegers(low, high, k):
    def count_even_odd_digits(n):
        even_count = 0
        odd_count = 0
        for digit in str(n):
            d = int(digit)
            if d % 2 == 0:
                even_count += 1
            else:
                odd_count += 1
        return even_count, odd_count

