    cols = len(grid[0])

    # Count the number of 1s in each row and column
    rowCount = [0] * rows
    colCount = [0] * cols

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                rowCount[i] += 1
                colCount[j] += 1

    # Count right triangles
    result = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                # If current cell has value 1, it can be the right angle vertex
                # Number of triangles where this cell is the right angle vertex
                # = (number of 1s in same row - 1) * (number of 1s in same column - 1)
                if rowCount[i] > 1 and colCount[j] > 1:
                    result += (rowCount[i] - 1) * (colCount[j] - 1)

    return result
