def minimize_partitions(s):
    n = len(s)

    def is_balanced(substr):
        if not substr:
            return False
        freq = {}
        for char in substr:
            freq[char] = freq.get(char, 0) + 1
        return len(set(freq.values())) == 1

    # dp[i] represents the minimum number of partitions for s[:i]
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        for j in range(i):
            if is_balanced(s[j:i]):
                dp[i] = min(dp[i], dp[j] + 1)

    return dp[n]
