def minimumChanges(s, k):
    n = len(s)

    # Check if a string is semi-palindrome and return minimum changes needed
    def get_min_changes(substr):
        length = len(substr)
        if length == 1:
            return float('inf')  # length 1 cannot be semi-palindrome

        min_changes = float('inf')

        # Try all possible divisors d where 1 <= d < length and length % d == 0
        for d in range(1, length):
            if length % d == 0:
                changes = 0
                # For each residue class modulo d, check if it forms a palindrome
                for r in range(d):
                    # Extract characters at positions with index % d == r
                    chars = []
                    for i in range(r, length, d):
                        chars.append(substr[i])

                    # Count changes needed to make this sequence a palindrome
                    left = 0
                    right = len(chars) - 1
                    while left < right:
                        if chars[left] != chars[right]:
                            changes += 1
                        left += 1
                        right -= 1

                min_changes = min(min_changes, changes)

        return min_changes if min_changes != float('inf') else float('inf')

    # Precompute the cost of making s[i:j+1] a semi-palindrome
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i, n):
            substr = s[i:j+1]
            cost[i][j] = get_min_changes(substr)

    # DP to find minimum total changes to partition into k substrings
    # dp[i][p] = minimum changes to partition s[:i] into p semi-palindrome substrings
    INF = float('inf')
    dp = [[INF] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for p in range(1, min(k, i) + 1):
            # Try all possible last substring ending at position i-1
            for j in range(p - 1, i):  # j is the start of the last substring (0-indexed)
                if dp[j][p-1] != INF:
                    dp[i][p] = min(dp[i][p], dp[j][p-1] + cost[j][i-1])

    return dp[n][k]
