        max_suffix_len = 0
        min_length = len(wordsContainer[0])

        for i, (word, word_len, orig_idx) in enumerate(container_info):
            suffix_len = get_common_suffix_length(word, query)

            # Update best match if this one is better
            if suffix_len > max_suffix_len:
                max_suffix_len = suffix_len
                min_length = word_len
                best_index = orig_idx
            elif suffix_len == max_suffix_len:
                # Same suffix length, check for shorter word
                if word_len < min_length:
                    min_length = word_len
                    best_index = orig_idx
                # Same length, the one with earlier index wins (we don't update)

        ans.append(best_index)

