def findPrimePairs(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num ** 0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    def get_primes_up_to_n(limit):
        if limit < 2:
            return []
        primes = []
        for i in range(2, limit + 1):
            if is_prime(i):
                primes.append(i)
        return primes

    primes = get_primes_up_to_n(n)
    prime_set = set(primes)
    result = []

    for x in primes:
        y = n - x
        if y >= x and y in prime_set:
            result.append([x, y])

    return result
