                # Calculate minimum adjacent swaps for row permutation
                row_swaps = 0
                row_arr = list(row_perm)
                # Bubble sort to count adjacent swaps
                for i in range(H):
                    for j in range(H - 1):
                        if row_arr[j] > row_arr[j + 1]:
                            row_arr[j], row_arr[j + 1] = row_arr[j + 1], row_arr[j]
