def solve():
    import sys
    from collections import defaultdict

    # Read input
    lines = sys.stdin.read().strip().split('\n')
    if not lines or not lines[0].strip():
        print(-1)
        return

    N, M = map(int, lines[0].split())

    # Build directed graph: edge A -> B means A is stronger than B
    stronger_than = defaultdict(set)  # person -> set of people they are stronger than
    weaker_than = defaultdict(set)  # person -> set of people who are stronger than them

    for i in range(1, M + 1):
        if i >= len(lines):
            break
        a, b = map(int, lines[i].split())
        stronger_than[a].add(b)
        weaker_than[b].add(a)

    # Use transitivity to infer more relationships (Floyd-Warshall style)
    # We'll compute who is stronger than whom using closure
    can_infer_stronger = [[False] * (N + 1) for _ in range(N + 1)]

    # Initial relationships
    for i in range(1, N + 1):
        for j in stronger_than[i]:
            can_infer_stronger[i][j] = True

    # Transitive closure
    for k in range(1, N + 1):
        for i in range(1, N + 1):
            for j in range(1, N + 1):
                if can_infer_stronger[i][k] and can_infer_stronger[k][j]:
                    can_infer_stronger[i][j] = True

    # Find all people who are stronger than every other person
    possible_strongest = []

    for candidate in range(1, N + 1):
        is_strongest = True
        for other in range(1, N + 1):
            if candidate == other:
                continue
            # Check if candidate is stronger than other
            if not can_infer_stronger[candidate][other]:
                is_strongest = False
                break
        if is_strongest:
            possible_strongest.append(candidate)

    # If exactly one strongest programmer, return it; otherwise return -1
    if len(possible_strongest) == 1:
        print(possible_strongest[0])
    else:
