def minimumBeautifulSubstrings(s):
    # Precompute all powers of 5 in binary that could fit in a string of length <= 15
    powers_of_5_binary = []
    power = 1
    while True:
        binary = bin(power)[2:]  # Convert to binary without '0b' prefix
        if len(binary) > 15:
            break
        powers_of_5_binary.append(binary)
        power *= 5

    # Sort by length (descending) for efficiency in matching
    powers_of_5_binary.sort(key=lambda x: len(x), reverse=True)

    def can_partition(string, start, memo):
        if start == len(string):
            return 0

        if start in memo:
            return memo[start]

        # If current character is '0', we cannot form a beautiful substring (due to leading zero)
        if string[start] == '0':
            memo[start] = float('inf')
            return float('inf')

        min_partitions = float('inf')

        # Try all possible substrings starting from current position
        for end in range(start + 1, len(string) + 1):
            substring = string[start:end]
            # Check if this substring is a power of 5 in binary and has no leading zeros
            if substring in powers_of_5_binary:
                result = can_partition(string, end, memo)
                if result != float('inf'):
                    min_partitions = min(min_partitions, 1 + result)

        memo[start] = min_partitions
        return min_partitions

    memo = {}
    result = can_partition(s, 0, memo)

    return result if result != float('inf') else -1
