def minimum_operations(x: int, y: int) -> int:
    from collections import deque

    if x == y:
        return 0

    # BFS to find minimum operations
    queue = deque([(x, 0)])  # (current_value, operations_count)
    visited = {x}

    while queue:
        current, ops = queue.popleft()

        # Try all possible operations
        next_states = []

        # Operation 1: Divide by 11 if multiple of 11
        if current % 11 == 0:
            next_states.append(current // 11)

        # Operation 2: Divide by 5 if multiple of 5
        if current % 5 == 0:
            next_states.append(current // 5)

        # Operation 3: Decrement by 1
        next_states.append(current - 1)

        # Operation 4: Increment by 1
        next_states.append(current + 1)

        for next_val in next_states:
            if next_val == y:
                return ops + 1

            if next_val > 0 and next_val not in visited:
                visited.add(next_val)
                queue.append((next_val, ops + 1))

    return -1  # This should not happen given the constraints
