def solve():
    import sys
    input = sys.stdin.read
    data = input().splitlines()

    N = int(data[0])
    R = data[1].strip()
    C = data[2].strip()

    # Since N is small (3 to 5), we can use backtracking
    grid = [['.' for _ in range(N)] for _ in range(N)]

    # Track counts of A, B, C in each row and column
    row_count = [{'A': 0, 'B': 0, 'C': 0} for _ in range(N)]
    col_count = [{'A': 0, 'B': 0, 'C': 0} for _ in range(N)]

    # Track leftmost and topmost characters
    row_leftmost = [None] * N
    col_topmost = [None] * N

    def is_valid(row, col, char):
        # Check if placing char at (row, col) violates any constraints
        if row_count[row][char] >= 1:
            return False
        if col_count[col][char] >= 1:
            return False

        # Check if this placement would violate leftmost constraint for this row
        if row_leftmost[row] is None or col < row_leftmost[row][1]:
            if char != R[row]:
                return False

        # Check if this placement would violate topmost constraint for this column
        if col_topmost[col] is None or row < col_topmost[col][0]:
            if char != C[col]:
                return False

        return True

    def place(row, col, char):
        grid[row][col] = char
        row_count[row][char] += 1
        col_count[col][char] += 1

        # Update leftmost for row
        if row_leftmost[row] is None or col < row_leftmost[row][1]:
            row_leftmost[row] = (char, col)

        # Update topmost for column
        if col_topmost[col] is None or row < col_topmost[col][0]:
            col_topmost[col] = (char, row)

    def unplace(row, col, char):
        grid[row][col] = '.'
        row_count[row][char] -= 1
        col_count[col][char] -= 1

        # Restore leftmost for row
        if row_leftmost[row] == (char, col):
            # Recompute leftmost
            row_leftmost[row] = None
            for j in range(N):
                if grid[row][j] != '.':
                    if row_leftmost[row] is None or j < row_leftmost[row][1]:
                        row_leftmost[row] = (grid[row][j], j)

        # Restore topmost for column
        if col_topmost[col] == (char, row):
            # Recompute topmost
            col_topmost[col] = None
            for i in range(N):
                if grid[i][col] != '.':
                    if col_topmost[col] is None or i < col_topmost[col][0]:
                        col_topmost[col] = (grid[i][col], i)

    def get_next_cell(row, col):
        if col == N - 1:
            return (row + 1, 0)
        else:
            return (row, col + 1)

    def backtrack(row, col):
        if row == N:
            # Check if all rows and columns have exactly one A, B, C
            for i in range(N):
                if row_count[i]['A'] != 1 or row_count[i]['B'] != 1 or row_count[i]['C'] != 1:
                    return False
                if col_count[i]['A'] != 1 or col_count[i]['B'] != 1 or col_count[i]['C'] != 1:
                    return False
            return True

        next_row, next_col = get_next_cell(row, col)

        # Try leaving the cell empty
        if backtrack(next_row, next_col):
            return True

        # Try placing A, B, C
        for char in 'ABC':
            if is_valid(row, col, char):
                place(row, col, char)
                if backtrack(next_row, next_col):
                    return True
                unplace(row, col, char)

        return False

    # First, check immediate contradictions
    # If any row i must have leftmost character R[i], but C[i] requires a different character at top of column i
    # We can't put R[i] at (i,0) if some other row j < i needs C[j] to be at (j,i) and it conflicts

    # Instead of complex upfront checks, use backtracking with the constraints

    # We need to ensure the leftmost and topmost constraints are respected
    # Start backtracking from (0,0)
    if backtrack(0, 0):
        print("Yes")
        for i in range(N):
            print(''.join(grid[i]))
    else:
        print("No")

